import 'dart:convert';
import 'dart:io';
void main(){const root='/private/tmp/dart3d-u3-outline-publication-control-20261028/r1/parent';for(final stage in ['baseline','control']){final files=Directory('$root/$stage/raw').listSync().whereType<File>().where((f)=>f.path.endsWith('.json')).map((f){final m=jsonDecode(f.readAsStringSync()) as Map<String,dynamic>;m['path']=f.path.replaceAll('.json','.rgba');return m;}).toList()..sort((a,b)=>double.parse(RegExp(r'time=([\d.]+)').firstMatch(a['label'])!.group(1)!).compareTo(double.parse(RegExp(r'time=([\d.]+)').firstMatch(b['label'])!.group(1)!)));final base=files.firstWhere((m)=>m['label'].startsWith('target ')&&m['label'].contains('mode=0'));final baseBytes=File(base['path']).readAsBytesSync();final result=<Map<String,Object>>[];for(final f in files.where((m)=>m['label'].startsWith('target ')||m['label'].startsWith('alpha-output '))){final bytes=File(f['path']).readAsBytesSync();var differing=0;final counts=<String,int>{};for(var i=0;i<bytes.length;i+=4){if(List.generate(4,(c)=>bytes[i+c]!=baseBytes[i+c]).any((v)=>v))differing++;final color=bytes.sublist(i,i+4).join(',');counts[color]=(counts[color]??0)+1;}final ordered=counts.entries.toList()..sort((a,b)=>b.value.compareTo(a.value));result.add({'label':f['label'],'changedFromActualOffPixels':differing,'topColorsBGRA':ordered.take(6).map((e)=>[e.key,e.value]).toList()});}File('$root/$stage/first-use.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(result));print(jsonEncode({'stage':stage,'results':result}));}}
